xml.Script:
        clWhite := 'FFFFFF';

        
        function IntToHex1(num);
        begin
            case (num) of
                10: Result := 'A';
                11: Result := 'B';
                12: Result := 'C';
                13: Result := 'D';
                14: Result := 'E';
                15: Result := 'F';
            else
                Result := IntToStr(num);
            end;
        end;

        
        function IntToHex2(num);
        begin
            Result := IntToHex1(num div 16) + IntToHex1(num mod 16);
        end;

        function RGB( R, G, B);
        begin
            Result := IntToHex2(int(255 * R)) + IntToHex2(int(255 * G)) + IntToHex2(int(255 * B));
        end;

        
        
        function HSVToHex(H, S, V);
        begin
            
            H := H - int(H);

            if not (S = 0) then begin // non-zero Saturation
                vh := H * 6;
                vi := int(vh);
                v1 := V * (1 - S);
                v2 := V * (1 - S * (vh - vi));
                v3 := V * (1 - S * (1 - (vh - vi)));

                case (vi) of
                    0 : RGB(  V, v3, v1);
                    1 : RGB( v2,  V, v1);
                    2 : RGB( v1,  V, v3);
                    3 : RGB( v1, v2,  V);
                    4 : RGB( v3, v1,  V);
                    5 : RGB(  V, v1, v2);
                end;
            end else
                RGB( V, V, V);
        end;

        N := 12;
        for i := 0 to N - 1 do
             Cols[i] := HSVToHex(i/N, 1.00, 1.00);

        W := 0.6;
        H := W / 4;

        sAngle := 2 * PI / N;

        // Cylinder parameters
        RC := W * 2 / 3;
        xc := W / 6 * 1.5;
        yc := W / 6 * 1;
        zc := W / 6 * 5;

        // White labels parameters
        LW := W * 1.001;
        LD := W * 0.1;
